CREATE TABLE [dbo].[ReportsCharts](	  [id] INT NOT NULL	, [reportName] NVARCHAR(100) COLLATE SQL_Latin1_General_CP1_CI_AS NOT NULL	, [chartType] NVARCHAR(1) COLLATE SQL_Latin1_General_CP1_CI_AS NOT NULL	, [x1] NVARCHAR(100) COLLATE SQL_Latin1_General_CP1_CI_AS NOT NULL	, [subX1] NVARCHAR(100) COLLATE SQL_Latin1_General_CP1_CI_AS NOT NULL	, [x2] NVARCHAR(100) COLLATE SQL_Latin1_General_CP1_CI_AS NOT NULL	, [subX2] NVARCHAR(100) COLLATE SQL_Latin1_General_CP1_CI_AS NOT NULL	, [countColumn] NVARCHAR(200) COLLATE SQL_Latin1_General_CP1_CI_AS NOT NULL	, [chartDescription] NVARCHAR(255) COLLATE SQL_Latin1_General_CP1_CI_AS NOT NULL	, [isTime] INT NOT NULL DEFAULT((0))	, CONSTRAINT [PK_ReportsCharts] PRIMARY KEY ([id] ASC, [reportName] ASC, [chartType] ASC))